def minOperations(nums, k):
    n = len(nums)
    # cnt[p][m] = number of elements at positions with parity p whose remainder is m
    cnt = [[0] * k for _ in range(2)]
    for i in range(n):
        cnt[i & 1][nums[i] % k] += 1

    def all_costs(c):
        # returns cost[r] = total cost to move every residue counted in c to residue r
        if sum(c) == 0:
            return [0] * k

        # circular distance between two residues
        def circ(a, b):
            d = abs(a - b)
            return min(d, k - d)

        cost = [0] * k
        # cost[0] and cost[1] are computed directly in O(k)
        for m in range(k):
            if c[m]:
                cost[0] += c[m] * circ(m, 0)
                cost[1] += c[m] * circ(m, 1)
        # second difference of the tent function is nonzero only at a few offsets
        if k % 2 == 0:
            spikes = [(0, 2), (k // 2, -2)]
        else:
            spikes = [(0, 2), ((k - 1) // 2, -1), ((k + 1) // 2, -1)]
        # roll forward: cost[r+1] = 2*cost[r] - cost[r-1] + sum of weighted spike counts
        for r in range(1, k - 1):
            extra = 0
            for d, w in spikes:
                extra += w * c[(r - d) % k]
            cost[r + 1] = 2 * cost[r] - cost[r - 1] + extra
        return cost

    ce = all_costs(cnt[0])   # cost of making every even-index element have residue x
    co = all_costs(cnt[1])   # cost of making every odd-index element have residue y

    # smallest and second smallest odd-group costs (remember where the smallest is)
    best1 = best2 = float('inf')
    idx1 = -1
    for y in range(k):
        if co[y] < best1:
            best2 = best1
            best1, idx1 = co[y], y
        elif co[y] < best2:
            best2 = co[y]

    # try every x, pairing it with the cheapest y that differs from x
    ans = float('inf')
    for x in range(k):
        other = best2 if x == idx1 else best1
        if ce[x] + other < ans:
            ans = ce[x] + other
    return ans
